contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to send when calling play. Must model both correct and incorrect values.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // read observable state before the call
        uint pot_before = c.pot();
        address bank_before = c.bank();
        uint balance_c_before = address(c).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after the call
        uint pot_after = c.pot();
        uint balance_c_after = address(c).balance;

        // The general rule:
        // - If the call reverted then it must be because amount != TICKET_AMOUNT, so pot unchanged and contract balance unchanged.
        // - If the call succeeded then amount must equal TICKET_AMOUNT. After a successful call, either the pot increased by amount (no payout case),
        //   or the pot was reset to 0 (payout case). In the payout case the contract balance decreases by at least the fee amount,
        //   and in the no-payout case the contract balance increases by exactly amount.

        // We cannot reference internal constants TICKET_AMOUNT or FEE_AMOUNT directly here, so express relationships using observable values.
        // For the payout case detection: pot_after == 0
        bool payout_happened = (pot_after == 0);

        // For no-payout detection: pot increased by amount
        bool no_payout = (pot_after == pot_before + amount);

        // If reverted: pot and contract balance must be unchanged and amount was not the exact ticket price (i.e., must not have behaved like success)
        // If not reverted: amount must have been accepted (we encode that by requiring either payout_happened or no_payout holds and balance changed accordingly).

        // Build the assert condition expressing the above general rule using only observable values.
        assert(
            // Case A: reverted -> pot and contract balance unchanged
            (reverted && pot_after == pot_before && balance_c_after == balance_c_before)
            ||
            // Case B: succeeded -> either no_payout or payout_happened with consistent balance change
            (!reverted && (
                // no payout: pot increased by amount and contract balance increased by amount
                (no_payout && balance_c_after == balance_c_before + amount)
                ||
                // payout: pot reset to 0 and contract balance is less than or equal to balance before + amount (because payout transfers out)
                (payout_happened && balance_c_after <= balance_c_before + amount)
            ))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call c.play{value: amount}() with amount provided by the caller.
    // The test observes address(c).balance and the InvMutTest contract balance before/after
    // to assert that when a payout happens (pot becomes 0) the caller received the pot minus fee,
    // and the bank received the fee. We cannot read internal bank balance, but transfers to bank
    // reduce address(c).balance by FEE_AMOUNT when payout happens while the caller receives pot-FEE.

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // read observable before-values
        uint beforePot = c.pot();
        uint beforeCBalance = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPot = c.pot();
        uint afterCBalance = address(c).balance;
        uint afterThis = address(this).balance;

        // general rule asserted for all inputs:
        // If call reverted then state didn't change (pot and balances unchanged).
        // If call did not revert and amount == TICKET_AMOUNT then either:
        //  - payout occurred: pot became 0, contract balance decreased by at least 1 (the fee),
        //    and caller's balance increased by (beforeCBalance - afterCBalance) - 0 or more (net received),
        //    and specifically the contract's pot is 0; OR
        //  - no payout: pot increased by amount and contract balance increased by amount.
        // We encode this as a single assert combining these observable consequences.

        assert(
            // if reverted then nothing observable changed
            (reverted && afterPot == beforePot && afterCBalance == beforeCBalance && afterThis == beforeThis)
            ||
            // if not reverted, two cases depending on whether pot reset to 0
            (!reverted && amount == C(address(c)).TICKET_AMOUNT() && (
                // payout case: pot becomes 0 and contract balance decreased by at least FEE_AMOUNT
                (afterPot == 0 && beforeCBalance >= afterCBalance && (beforeCBalance - afterCBalance) >= C(address(c)).FEE_AMOUNT()
                    && afterThis >= beforeThis)
                ||
                // no payout case: pot increased by amount and contract balance increased by amount
                (afterPot == beforePot + amount && afterCBalance == beforeCBalance + amount)
            ))
        );
    }

    receive() external payable {}
}

