        // - If amount == TICKET_AMOUNT then call must NOT revert, and either:
        //     a) no payout: pot increased by amount, contract balance increased by amount, caller balance unchanged;
        //     b) payout happened: pot == 0, contract balance decreased (compared to before), and caller balance increased (received payout).
        // We cannot reference TICKET_AMOUNT directly, so express equality/inequality by observing behavior.

        // Implemented as single assert combining both cases.
        assert(
            // Case: call reverted -> must be when amount != ticket price, observable state unchanged
            (reverted && afterPot == beforePot && afterCBalance == beforeCBalance)
            ||
            // Case: not reverted -> must be amount == ticket price and either payout or no-payout with described balance effects
            (!reverted && (
                // No-payout branch: pot increased by exactly amount and contract balance increased by amount and caller balance unchanged
                (afterPot == beforePot + amount && afterCBalance == beforeCBalance + amount && afterMyBalance == beforeMyBalance)
                ||
                // Payout branch: pot reset to 0, contract balance decreased (paid out + fee), and caller balance increased (received payout)
                (afterPot == 0 && afterCBalance < beforeCBalance && afterMyBalance > beforeMyBalance)
            ))
        );
    }

